/* LM75 family: temperature register is signed and left-justified.
 * Verify your actual chip marking before choosing resolution:
 *  9 bits: standard LM75, 0.5 C/LSB (7 low unused bits)
 * 11 bits: e.g. NXP LM75A, 0.125 C/LSB (5 low unused bits).
 * Default 11 also reads a standard 9-bit LM75 correctly when unused
 * low bits are zero, as required by the standard LM75 register format.
 * Select 9 if your specific 9-bit clone has unspecified low bits.
 * A low-pass filter cannot create more physical sensor accuracy/resolution.
 * One independent read per sensorUpdate (~250 ms). Avoid multiple reads
 * within a single sensor conversion; those would be copies of one sample.
 * Use 0 offset / unit gain until calibrated against a reference thermometer. */
#define LM75_ADDR_HAL                  (0x48u << 1)
#define LM75_TEMP_REGISTER            0x00u
#define LM75_CONFIG_REGISTER          0x01u
#define LM75_RESOLUTION_BITS          11u /* Preserves LM75A 0.125 C resolution */
#define LM75_TEMP_GAIN                 1.0f
#define LM75_TEMP_OFFSET_C             0.0f
#define LM75_I2C_RETRIES               2u /* Maximum attempts, no unbounded wait */
#define LM75_RETRY_DELAY_MS            2u
#define LM75_HISTORY_STALE_MS       1000u
#define LM75_FILTER_ALPHA              0.25f
#define LM75_FILTER_FAST_ALPHA         0.70f
#define LM75_FILTER_FAST_STEP_C        2.0f

#if (LM75_RESOLUTION_BITS != 9u) && (LM75_RESOLUTION_BITS != 11u)
#error "Select LM75_RESOLUTION_BITS 9 or 11 after confirming the IC variant"
#endif

/* ADS1115: single-ended AIN0..AIN3, 128 SPS, PGA +/-4.096 V.
 * IMPORTANT: Set VDD to the MEASURED ADS1115 supply voltage (mV).
 * PGA full-scale is NOT permission to drive a pin above VDD.
 * This software rail check cannot protect hardware against overvoltage.
 * Hardware must keep ALL AIN pins inside [GND, VDD] under ALL conditions. */
#define ADS1115_ADDR_HAL             (0x4Au << 1)
#define ADS1115_VDD_MV                3300u /* CHANGE TO MEASURED VDD */
