#define ADS1115_CONV_TIMEOUT_MS        18u
#define ADS1115_READS_PER_TAP           3u
#define ADS1115_REPEAT_SPREAD_MV       35u /* at AIN, not battery tap */
#define ADS1115_CONFIG_BASE       0x8383u

