static float clampFloat(float x, float lo, float hi)
{
    return (x < lo) ? lo : ((x > hi) ? hi : x);
}

static uint16_t milliUnsigned(float x)
{
    x = clampFloat(x * 1000.0f, 0.0f, 65535.0f);
    return (uint16_t)(x + 0.5f);
}

static int16_t milliSigned(float x)
{
    x = clampFloat(x * 1000.0f, -32768.0f, 32767.0f);
    return (int16_t)(x >= 0.0f ? x + 0.5f : x - 0.5f);
}

static float getPackSocFromVoltage(float packV)
{
    if (packV >= OCV_TABLE[0]) return SOC_TABLE[0];
    if (packV <= OCV_TABLE[PACK_OCV_TABLE_SIZE-1u])
        return SOC_TABLE[PACK_OCV_TABLE_SIZE-1u];
    for (uint8_t i = 0u; i < PACK_OCV_TABLE_SIZE - 1u; ++i) {
        if (packV <= OCV_TABLE[i] && packV >= OCV_TABLE[i+1u]) {
            const float a = (packV - OCV_TABLE[i+1u]) /
                            (OCV_TABLE[i] - OCV_TABLE[i+1u]);
            return SOC_TABLE[i+1u] + a * (SOC_TABLE[i] - SOC_TABLE[i+1u]);
        }
    }
    return 0.0f;
}

static bool adcRead(uint32_t channel, uint32_t *raw)
{
    ADC_ChannelConfTypeDef cfg = {0};
    cfg.Channel = channel;
    cfg.Rank = ADC_REGULAR_RANK_1;
    cfg.SamplingTime = ADC_SAMPLETIME_239CYCLES_5;
    if (HAL_ADC_ConfigChannel(&hadc1, &cfg) != HAL_OK) return false;
    if (HAL_ADC_Start(&hadc1) != HAL_OK) return false;
    if (HAL_ADC_PollForConversion(&hadc1, ADC_TIMEOUT_MS) != HAL_OK) {
        (void)HAL_ADC_Stop(&hadc1);
        return false;
    }
    *raw = HAL_ADC_GetValue(&hadc1);
    (void)HAL_ADC_Stop(&hadc1);
    return true;
}

/* One acquisition window:
 * 1) collect 32 ADC samples, spaced 1 ms apart to cover part of the
 *    low-frequency interference cycle (not only 32 adjacent conversions);
 * 2) discard 3 lowest and 3 highest readings to suppress isolated spikes;
 * 3) apply the original voltage calibration and the requested -0.968 A;
 * 4) apply an adaptive EMA to DISPLAY/TELEMETRY only;
 * 5) return the unlagged trimmed value separately for SOC integration.
 *
 * A digital filter reduces random noise, not ADC gain, Vref, temperature
 * drift, or an incorrectly calibrated ACS712 sensitivity. */
static bool readCurrentA(float *displayAmps, float *socAmps)
{
    if ((displayAmps == NULL) || (socAmps == NULL))
        return false;

    uint16_t values[ACS712_NUM_SAMPLES];

    for (uint8_t i = 0u; i < ACS712_NUM_SAMPLES; ++i) {
        uint32_t raw = 0u;
        if (!adcRead(ADC_CHANNEL_6, &raw) || (raw > 4095u)) {
            g_bmsAcsReadErrorCount++;
            return false;
        }

        values[i] = (uint16_t)raw;
        if ((i + 1u) < ACS712_NUM_SAMPLES)
            HAL_Delay(ACS712_SAMPLE_SPACING_MS);
    }

    /* Insertion sort: only 32 values, small fixed memory/CPU overhead. */
    for (uint8_t i = 1u; i < ACS712_NUM_SAMPLES; ++i) {
        const uint16_t key = values[i];
        uint8_t j = i;
        while ((j > 0u) && (values[j - 1u] > key)) {
            values[j] = values[j - 1u];
            --j;
        }
        values[j] = key;
    }

    g_bmsAcsRawMin = values[0u];
    g_bmsAcsRawMax = values[ACS712_NUM_SAMPLES - 1u];

    /* A clipped central distribution cannot be recovered by filtering. */
    if ((values[ACS712_TRIM_EACH_END] <= 1u) ||
        (values[ACS712_NUM_SAMPLES - ACS712_TRIM_EACH_END - 1u] >= 4094u)) {
        g_bmsAcsReadErrorCount++;
        return false;
    }

    uint32_t sum = 0u;
    for (uint8_t i = ACS712_TRIM_EACH_END;
         i < (ACS712_NUM_SAMPLES - ACS712_TRIM_EACH_END);
         ++i) {
        sum += values[i];
    }

    const float meanRaw = (float)sum /
        (float)(ACS712_NUM_SAMPLES - 2u * ACS712_TRIM_EACH_END);
    g_bmsAcsTrimmedAdcRaw = (uint16_t)(meanRaw + 0.5f);

    const float adcV = meanRaw * (ADC_REFERENCE_V / 4095.0f);
    const float correctedV = adcV * ACS712_GAIN + ACS712_ADC_OFFSET_V;
    const float instantA = ((correctedV - ACS712_VZERO_V) /
                            ACS712_SENSITIVITY_V_PER_A) -
                           ACS712_CURRENT_OFFSET_A;

    /* Preserve the existing broad plausibility check. Any bad sample is
     * invalid and must not drive LCD, SOC, or a new telemetry-valid flag. */
    if (!((instantA > -30.0f) && (instantA < 30.0f))) {
        g_bmsAcsReadErrorCount++;
        return false;
    }

    g_bmsAcsInstantA = instantA;

    if (!s_haveCurrentFilter) {
        s_currentA = instantA;
        s_haveCurrentFilter = true;
    } else {
        const float deltaA = instantA - s_currentA;
        const float absDeltaA = (deltaA < 0.0f) ? -deltaA : deltaA;
        const float alpha = (absDeltaA >= ACS712_FILTER_FAST_STEP_A)
            ? ACS712_FILTER_FAST_ALPHA
            : ACS712_FILTER_ALPHA;
        s_currentA += alpha * deltaA;
    }

    g_bmsAcsFilteredA = s_currentA;
    *displayAmps = s_currentA;
    *socAmps = instantA;
    return true;
}

/* ADS1115 acquisition: every single-shot is explicitly started and polled
 * to completion, then the matching channel conversion is read. A fixed delay
 * alone can accidentally return an old conversion after I2C/timing trouble.
 * Return false on ANY failure: stale data are never reused. */
static bool adsFail(uint8_t channel, uint8_t stage)
{
    g_bmsAdsErrorChannel = channel;
    g_bmsAdsErrorStage = stage;
    g_bmsAdsReadErrorCount++;
    return false;
}

static bool adsReadOneRaw(uint8_t channel, int16_t *raw)
{
    if ((channel > 3u) || (raw == NULL)) return adsFail(channel, 2u);

    const uint16_t config = (uint16_t)(ADS1115_CONFIG_BASE |
                                     ((uint16_t)(channel + 4u) << 12));
    uint8_t command[3] = {0x01u, (uint8_t)(config >> 8), (uint8_t)config};
    if (HAL_I2C_Master_Transmit(&hi2c1, ADS1115_ADDR_HAL, command, 3u,
                                I2C_TIMEOUT_MS) != HAL_OK)
        return adsFail(channel, 1u);

    const uint32_t begin = HAL_GetTick();
    bool complete = false;
    do {
        uint8_t cfg[2];
        if (HAL_I2C_Mem_Read(&hi2c1, ADS1115_ADDR_HAL, 0x01u,
                             I2C_MEMADD_SIZE_8BIT, cfg, 2u,
                             I2C_TIMEOUT_MS) != HAL_OK)
            return adsFail(channel, 2u);

        const uint16_t status = (uint16_t)(((uint16_t)cfg[0] << 8) | cfg[1]);
        /* Ensure that neither another driver nor an interrupted write has
         * silently changed the requested multiplexer or PGA setting. */
        if ((status & 0x7E00u) != (config & 0x7E00u))
            return adsFail(channel, 2u);
        if ((status & 0x8000u) != 0u) {
            complete = true;
            break;
        }
        HAL_Delay(1u);
    } while ((uint32_t)(HAL_GetTick() - begin) < ADS1115_CONV_TIMEOUT_MS);

    if (!complete) return adsFail(channel, 3u);

    uint8_t data[2];
    if (HAL_I2C_Mem_Read(&hi2c1, ADS1115_ADDR_HAL, 0x00u,
                         I2C_MEMADD_SIZE_8BIT, data, 2u,
                         I2C_TIMEOUT_MS) != HAL_OK)
        return adsFail(channel, 4u);

    *raw = (int16_t)(((uint16_t)data[0] << 8) | data[1]);

    /* For +/-4.096 V PGA each raw code = 0.125 mV. Since these are
     * single-ended readings, negative/near-FSR/near-VDD are invalid.
     * Rail checks detect SOME clipping, but cannot validate the input wiring. */
    if ((*raw < 0) || (*raw >= 32760) ||
        ((uint32_t)(*raw) >=
         ((uint32_t)(ADS1115_VDD_MV - ADS1115_RAIL_MARGIN_MV) * 8u)))
        return adsFail(channel, 5u);

    return true;
}

/* Three independent observations of EACH tap. Interleave the four channels
 * over three rounds to reduce intra-pack timing skew between taps.
 * Median rejects one impulsive outlier; a consistency check rejects data
 * without at least two reasonably agreeing readings. */
static bool adsReadPackTaps(float tapsV[4])
{
    int16_t raw[4][ADS1115_READS_PER_TAP];

    for (uint8_t round = 0u; round < ADS1115_READS_PER_TAP; ++round)
        for (uint8_t ch = 0u; ch < 4u; ++ch)
            if (!adsReadOneRaw(ch, &raw[ch][round])) return false;

    for (uint8_t ch = 0u; ch < 4u; ++ch) {
        int16_t low = raw[ch][0u];
        int16_t mid = raw[ch][1u];
        int16_t high = raw[ch][2u];
        if (low > mid) { int16_t tmp = low; low = mid; mid = tmp; }
        if (mid > high) { int16_t tmp = mid; mid = high; high = tmp; }
        if (low > mid) { int16_t tmp = low; low = mid; mid = tmp; }

        /* Difference in ADS codes * 0.125 mV/code. All three far apart
         * indicates a noisy/rapidly moving input; do NOT invent a value. */
        const uint16_t closeCodes = (uint16_t)(ADS1115_REPEAT_SPREAD_MV * 8u);
        if (((uint16_t)(mid - low) > closeCodes) &&
            ((uint16_t)(high - mid) > closeCodes))
            return adsFail(ch, 6u);

        const uint16_t bestPairSpread = ((mid - low) < (high - mid))
            ? (uint16_t)(mid - low) : (uint16_t)(high - mid);
        g_bmsAdsSpreadInput_mV[ch] = (uint16_t)((bestPairSpread + 4u) / 8u);
        g_bmsAdsRawMedian[ch] = mid;

        const float inputV = (float)mid * 0.000125f;
        tapsV[ch] = inputV * DIV_RATIO[ch] * CALIBRATION[ch] *
                    ADS_TAP_GAIN[ch] + ADS_TAP_OFFSET_V[ch];
        g_bmsAdsTapRawV[ch] = tapsV[ch];
    }

    g_bmsAdsErrorStage = 0u;
    g_bmsAdsErrorChannel = 0xFFu;
    return true;
}

/* Decode a signed, left-justified LM75 temperature register without
 * depending on implementation-defined right shifts of negative values.
 * Ignore unused LSBs according to the confirmed chip resolution. */
static float lm75DecodeC(uint16_t word)
{
    const uint16_t mask = (uint16_t)(0xFFFFu << (16u - LM75_RESOLUTION_BITS));
    const uint16_t valid = (uint16_t)(word & mask);
    const int32_t signedRaw = ((valid & 0x8000u) != 0u)
        ? ((int32_t)valid - 65536)
        : (int32_t)valid;
    return (float)signedRaw * (1.0f / 256.0f);
}

static float lm75Median3(float a, float b, float c)
{
    if (a > b) { const float t = a; a = b; b = t; }
    if (b > c) { const float t = b; b = c; c = t; }
    if (a > b) { const float t = a; a = b; b = t; }
    return b;
}

static void lm75ResetHistory(void)
{
    s_lm75HistoryCount = 0u;
    s_lm75HistoryIndex = 0u;
    s_lm75HasFilter = false;
    g_bmsLm75HistoryCount = 0u;
    g_bmsLm75FilterResetCount++;
}

static bool lm75Fail(uint8_t stage)
{
    g_bmsLm75ErrorStage = stage;
    g_bmsLm75ReadErrorCount++;
    /* Do not set TEMP_VALID and do not reuse the previous reading as new.
     * After an extended outage, clear the 3-sample median and EMA so that
     * old thermal values cannot contaminate the first recovered sample. */
    if (s_lm75HasFilter &&
        ((uint32_t)(HAL_GetTick() - g_bmsLm75LastGoodTick_ms) >=
         LM75_HISTORY_STALE_MS)) {
        lm75ResetHistory();
    }
    return false;
}

/* Returns one freshly acquired, filtered temperature for LCD/UART.
 * A limited I2C retry avoids a transient NACK on the bus shared with LCD
 * and ADS1115. Config register is read-only here: shutdown (bit 0) is
 * diagnosed, not silently cleared by firmware. */
static bool readPackTemperature(float *tempC)
{
    if (tempC == NULL) return lm75Fail(1u);

    uint8_t tempBuf[2] = {0u, 0u};
    uint8_t config = 0u;
    uint8_t errorStage = 1u;
    bool readOK = false;

    for (uint8_t attempt = 0u; attempt < LM75_I2C_RETRIES; ++attempt) {
        if (HAL_I2C_Mem_Read(&hi2c1, LM75_ADDR_HAL, LM75_TEMP_REGISTER,
                             I2C_MEMADD_SIZE_8BIT, tempBuf, 2u,
                             I2C_TIMEOUT_MS) != HAL_OK) {
            errorStage = 1u;
        } else if (HAL_I2C_Mem_Read(&hi2c1, LM75_ADDR_HAL,
                                    LM75_CONFIG_REGISTER,
                                    I2C_MEMADD_SIZE_8BIT, &config, 1u,
                                    I2C_TIMEOUT_MS) != HAL_OK) {
            errorStage = 2u;
        } else {
            readOK = true;
            break;
        }

        if ((attempt + 1u) < LM75_I2C_RETRIES)
            HAL_Delay(LM75_RETRY_DELAY_MS);
    }

    if (!readOK) return lm75Fail(errorStage);
    if ((config & 0x01u) != 0u) return lm75Fail(3u); /* Shutdown: stale register */

    const uint16_t word = (uint16_t)(((uint16_t)tempBuf[0] << 8) | tempBuf[1]);
    const float physicalC = lm75DecodeC(word);
    if (!((physicalC >= -55.0f) && (physicalC <= 125.0f)))
        return lm75Fail(4u);

    /* User-defined gain/offset are 1/0 until reference-calibrated. */
    const float measuredC = physicalC * LM75_TEMP_GAIN + LM75_TEMP_OFFSET_C;
    if (!((measuredC >= -55.0f) && (measuredC <= 125.0f)))
        return lm75Fail(4u);

    const uint32_t tick = HAL_GetTick();
    if (s_lm75HasFilter &&
        ((uint32_t)(tick - g_bmsLm75LastGoodTick_ms) >=
         LM75_HISTORY_STALE_MS)) {
        lm75ResetHistory();
    }

    g_bmsLm75RawWord = word;
    g_bmsLm75RawC = measuredC;
    g_bmsLm75LastGoodTick_ms = tick;
    g_bmsLm75ReadOkCount++;
    g_bmsLm75ErrorStage = 0u;

    s_lm75HistoryC[s_lm75HistoryIndex] = measuredC;
    s_lm75HistoryIndex = (uint8_t)((s_lm75HistoryIndex + 1u) % 3u);
    if (s_lm75HistoryCount < 3u) s_lm75HistoryCount++;
    g_bmsLm75HistoryCount = s_lm75HistoryCount;

    float medianC = measuredC;
    if (s_lm75HistoryCount == 2u)
        medianC = (s_lm75HistoryC[0] + s_lm75HistoryC[1]) * 0.5f;
    else if (s_lm75HistoryCount == 3u)
        medianC = lm75Median3(s_lm75HistoryC[0],
                               s_lm75HistoryC[1],
                               s_lm75HistoryC[2]);

    g_bmsLm75MedianC = medianC;
    if (!s_lm75HasFilter) {
        s_lm75FilteredC = medianC;
        s_lm75HasFilter = true;
    } else {
        const float delta = medianC - s_lm75FilteredC;
        const float absDelta = (delta < 0.0f) ? -delta : delta;
        const float alpha = (absDelta >= LM75_FILTER_FAST_STEP_C)
            ? LM75_FILTER_FAST_ALPHA : LM75_FILTER_ALPHA;
        s_lm75FilteredC += alpha * delta;
    }

    g_bmsLm75FilteredC = s_lm75FilteredC;
    *tempC = s_lm75FilteredC;
    return true;
}

/* Single source of truth for the physical load state.
 *
 * enable = true:
 *   PA7  = HIGH  -> load/MOSFET ON
 *   PC13 = LOW   -> on-board LED ON (Blue Pill active-low LED)
 *
 * enable = false:
 *   PA7  = LOW   -> load/MOSFET OFF
 *   PC13 = HIGH  -> on-board LED OFF
 */
static void setLoadOutput(bool enable)
{
    mosfetState = enable ? 1u : 0u;

    HAL_GPIO_WritePin(
        BMS_LOAD_GPIO_PORT,
        BMS_LOAD_PIN,
        enable ? GPIO_PIN_SET : GPIO_PIN_RESET);

    HAL_GPIO_WritePin(
        BMS_LED_GPIO_PORT,
        BMS_LED_PIN,
        enable ? BMS_LED_ON_STATE : BMS_LED_OFF_STATE);
}

static void latchProtectionFault(void)
{
    g_protectionLatched = true;
    setLoadOutput(false);
}

/* Apply the manual output request from the push button.
 * OFF is always accepted. ON is accepted only when the BMS can verify that
 * measurements are valid and no protection fault is latched. */
static void handleButtonPress(void)
{
    g_buttonPressCnt++;

    if (mosfetState != 0u) {
        setLoadOutput(false);
        return;
    }

    if (g_protectionLatched || !g_measurementValid) {
        g_buttonRejectedCnt++;
        return;
    }

    setLoadOutput(true);
}

static void sensorUpdate(uint32_t now)
{
    BMS_Telemetry_t sample = {0};
    float taps[4], cells[4], currentA = 0.0f, currentSocA = 0.0f, tempC = 0.0f;
    bool voltageOK = adsReadPackTaps(taps), currentOK, tempOK;
    currentOK = readCurrentA(&currentA, &currentSocA);
    tempOK = readPackTemperature(&tempC);
    if (voltageOK) {
        cells[0] = taps[0];
        cells[1] = taps[1] - taps[0];
        cells[2] = taps[2] - taps[1];
        cells[3] = taps[3] - taps[2];
        /* Reject broken taps/implausible data before protection & reporting.
         * These are data validity bounds, not the BMS cutoff thresholds. */
        if (taps[3] < 7.0f || taps[3] > 18.0f) voltageOK = false;
        for (uint8_t i = 0u; i < 4u; ++i) {
            g_bmsAdsCellRawV[i] = cells[i];
            if (cells[i] < 1.5f || cells[i] > 4.5f) voltageOK = false;
        }
        if (!voltageOK) (void)adsFail(0xFFu, 7u);
        else g_bmsAdsValidWindowCount++;
    }

    g_measurementValid = voltageOK && currentOK;
    if (!g_measurementValid) {
        /* Fail-safe: do not allow an ENABLE command while unable to measure. */
        latchProtectionFault();
    }
    if (voltageOK) {
        /* Filter cumulative tap voltage and subtract AFTER filtering.
         * This preserves Cell1+...+Cell4 == filtered tap4 by construction.
         * Raw/unfiltered taps are STILL used for immediate pack safety. */
        if (!s_haveFilter) {
            for (uint8_t i = 0u; i < 4u; ++i) s_filteredTapV[i] = taps[i];
            s_haveFilter = true;
        } else {
            for (uint8_t i = 0u; i < 4u; ++i)
                s_filteredTapV[i] += EMA_ALPHA * (taps[i] - s_filteredTapV[i]);
        }
        Cell1 = s_filteredTapV[0];
        Cell2 = s_filteredTapV[1] - s_filteredTapV[0];
        Cell3 = s_filteredTapV[2] - s_filteredTapV[1];
        Cell4 = s_filteredTapV[3] - s_filteredTapV[2];
        Cell_Tong = s_filteredTapV[3];
        for (uint8_t i = 0u; i < 4u; ++i) {
            float value = (i == 0u) ? Cell1 : (i == 1u) ? Cell2 :
                          (i == 2u) ? Cell3 : Cell4;
            sample.cell_mV[i] = milliUnsigned(value);
        }
        sample.pack_mV = milliUnsigned(Cell_Tong);
        sample.flags |= BMS_FLAG_VOLTAGE_VALID;
        /* Evaluate HARD pack limits with the unfiltered actual sample. */
        if (taps[3] > PACK_OVERVOLT_V || taps[3] < PACK_UNDERVOLT_V)
            latchProtectionFault();
    }
    if (currentOK) {
        s_currentA = currentA;
        sample.current_mA = milliSigned(s_currentA);
        sample.flags |= BMS_FLAG_CURRENT_VALID;
    }
    if (tempOK) {
        /* Round to the nearest centi-degree, including negative values. */
        sample.pack_temp_cC = (int16_t)((tempC >= 0.0f)
            ? (tempC * 100.0f + 0.5f)
            : (tempC * 100.0f - 0.5f));
        sample.flags |= BMS_FLAG_TEMP_VALID;
    }

    if (voltageOK && currentOK) {
        if (!s_socInitialized && now >= SOC_INIT_AFTER_MS) {
            SOC = getPackSocFromVoltage(Cell_Tong);
            s_socInitialized = true;
            s_lastCoulombMs = now;
        } else if (s_socInitialized) {
            const uint32_t elapsedMs = now - s_lastCoulombMs;
            s_lastCoulombMs = now;
            /* Positive ACS712 current means discharge; negative means charge.
             * Validate direction on your hardware before relying on SOC. */
            SOC -= (currentSocA * (float)elapsedMs /
                   (3600000.0f * BATTERY_CAPACITY_AH)) * 100.0f;
            SOC = clampFloat(SOC, 0.0f, 100.0f);
        }
        if (taps[3] > PACK_OVERVOLT_V) SOC = 100.0f;
        if (taps[3] < PACK_UNDERVOLT_V) SOC = 0.0f;
        if (s_socInitialized) {
            sample.soc_centi_pct = (uint16_t)(SOC * 100.0f + 0.5f);
            sample.flags |= BMS_FLAG_SOC_VALID;
        }
    }
    sample.output_enabled = mosfetState;
    if (g_protectionLatched) sample.flags |= BMS_FLAG_FAULT_LATCHED;
    sample.sampled_at_ms = now;
    s_latest = sample;
}

void BMS_App_Init(void)
{
    /* Local protection stays active independently of ESP32/Internet.
     * Start with load OFF and PC13 LED OFF. */
    setLoadOutput(false);

    /* Debounce module initializes all four slots; only PB5 is enabled. */
    BMS_Buttons_Init();
    g_buttonPressCnt = 0u;
    g_buttonRejectedCnt = 0u;
    g_buttonStableState = BMS_Buttons_GetStableState(BMS_BUTTON_1_LOAD);
    if (HAL_ADCEx_Calibration_Start(&hadc1) != HAL_OK) Error_Handler();
    /* Begin 3-second SolGrid splash, without delaying BMS/UART. */
    BMS_LCD_Init(HAL_GetTick());
    if (BMS_Comm_Init(&huart2) != HAL_OK) Error_Handler();
    if (HAL_TIM_Base_Start_IT(&htim2) != HAL_OK) Error_Handler();
}

void BMS_App_Process(void)
{
    static bool started = false;
    static uint32_t lastSensorMs;
    const uint32_t now = HAL_GetTick();
    if (!started) {
        lastSensorMs = now - SENSOR_INTERVAL_MS;
        started = true;
    }
    if ((uint32_t)(now - lastSensorMs) >= SENSOR_INTERVAL_MS) {
        lastSensorMs = now;
        sensorUpdate(now);
    }

    /* Consume button events in main context, never inside TIM2 IRQ.
     * Process AFTER the latest safety measurements, so a newly-detected
     * protection fault cannot be overridden by an ON request. */
    g_buttonStableState = BMS_Buttons_GetStableState(BMS_BUTTON_1_LOAD);
    while (BMS_Buttons_TakePress(BMS_BUTTON_1_LOAD)) {
        handleButtonPress();
    }
    /* Spare button slots 2..4 are intentionally not assigned any action. */
    s_latest.output_enabled = mosfetState;
    if (g_protectionLatched) s_latest.flags |= BMS_FLAG_FAULT_LATCHED;

    BMS_Comm_Service(&s_latest, HAL_GetTick());
    /* Display stays non-blocking for the 3 s splash. */
    BMS_LCD_Process(&s_latest, HAL_GetTick(), true);
}

/* HAL callbacks implemented OUTSIDE generated main.c. Do not duplicate.
 * This callback is a 1 ms event producer, with no I2C/output switching. */
void HAL_TIM_PeriodElapsedCallback(TIM_HandleTypeDef *htim)
{
    if (htim->Instance == TIM2)
        BMS_Buttons_Tick1ms();
}

void HAL_UART_RxCpltCallback(UART_HandleTypeDef *huart)
{
    BMS_Comm_OnRxByte(huart);
}

void HAL_UART_ErrorCallback(UART_HandleTypeDef *huart)
{
    BMS_Comm_OnUartError(huart);
}
